; draw_test_grid  ($BE01)
; -> src/game/main/gp2_4_svc.js
; Draw the cross-hatch test pattern over the tilemap $0000-$03FF (codes only).
; Called from: $BD82 service_loop
;------------------------------------------------------------------------------
draw_test_grid:
BE01: CE 00 00        LDU    #$0000
BE04: 8D 0F           BSR    grid_row_pair
BE06: C6 0E           LDB    #$0E

