;------------------------------------------------------------------------------
; irq_main  ($C000)
; -> src/game/main/gp2_3b_irq.js
; Main CPU vblank IRQ (also the SWI/FIRQ/NMI vector, never used).
;   - kick the watchdog and clear/mask the IRQ latch;
;   - operator stats display (DSWA SW1:6), demo-sound gate;
;   - DSW service switch on -> jump to service_mode (never returns);
;   - 56XX credits >= 10 in the tens nibble -> coin_jammed (hang);
;   - round-advance DIP on -> round_select loop (P1 up = next stage);
;   - re-enable the IRQ latch early (the CPU's I flag still masks it
;     until RTI), update the play clock and the 1UP/2UP blink;
;   - copy the flip flag; clear $1E31+2n for each occupied formation slot n;
;   - coin inserted (56XX nibble 2): coin sound; during attract,
;     abort the demo and restart attract at attract_loop (the stack is
;     abandoned; attract_loop never returns);
;   - copy main-owned sprites from the shadow buffers ($0EE2-$0F33 +
;     banks $1600/$1E00) into sprite RAM slots 40-63, mirrored when the
;     screen is flipped; park the unused slots (all 0);
;   - starfield scroll direction; frame counter $1016/$1015;
;   - frame rendezvous with the sub CPU: wait for $10AF = $11 (sub
;     finished its frame), answer $22, RTI.
; Vector: SWI3, SWI2, FIRQ, IRQ, SWI, NMI
;------------------------------------------------------------------------------
irq_main:
C000: B6 7C 00        LDA    WATCHDOG        ; kick the watchdog [$7C00]
C003: B7 7C 00        STA    IRQ_OFF_MAIN    ; clear and mask this IRQ [$7C00]
C006: BD FC DF        JSR    operator_stats  ; operator stats (SW1:6)
C009: B6 09 F4        LDA    attract_flag    ; [$09F4]
C00C: 27 03           BEQ    lC011
C00E: BD DF 27        JSR    sound_demo_gate

lC011:
C011: B6 68 14        LDA    IO58XX+$04      ; DSW service switch [$6814] 58XX
                                             ; DSWB hi (diff, svc)
C014: 84 08           ANDA   #$08
C016: 10 26 F6 DC     LBNE   service_mode
C01A: FC 68 00        LDD    IO56XX          ; coin jam test. QUIRK: 16-bit
                                             ; SUBD #$0A0A: jams on tens >= $B,
                                             ; or tens $A with units >= $A
                                             ; [$6800] 56XX credits tens
C01D: 84 0F           ANDA   #$0F
C01F: C4 0F           ANDB   #$0F
C021: 83 0A 0A        SUBD   #$0A0A
C024: 10 24 01 91     LBCC   coin_jammed
C028: B6 68 13        LDA    IO58XX+$03      ; round advance DIP [$6813] 58XX
                                             ; DSWB lo (rnd adv)
C02B: 84 08           ANDA   #$08
C02D: 10 26 01 32     LBNE   round_select

irq_main_normal:
C031: B7 74 00        STA    IRQ_ON_MAIN     ; IRQ latch on again; QUIRK: A
                                             ; goes to the IRQ latch: 0
                                             ; normally, $20 after round_select
                                             ; [$7400]
C034: BD D0 7A        JSR    irq_timers
C037: 96 2C           LDA    <flip_screen    ; flip flag -> hardware [$102C]
C039: B7 1F 7F        STA    FLIP_SCREEN     ; [$1F7F]
C03C: 8E 18 60        LDX    #formation_flags ; [#$1860]
C03F: C6 FE           LDB    #$FE

lC041:
C041: CB 02           ADDB   #$02
C043: A6 80           LDA    ,X+
C045: 8C 18 8D        CMPX   #$188D          ; BUG: tested after LDA ,X+: the
                                             ; last slot $188C is read but
                                             ; never tested
C048: 27 0B           BEQ    irq_check_coin
C04A: 84 01           ANDA   #$01
C04C: 27 F3           BEQ    lC041
C04E: CE 1E 31        LDU    #$1E31
C051: 6F C5           CLR    B,U
C053: 20 EC           BRA    lC041

irq_check_coin:
C055: B6 68 02        LDA    IO56XX+$02      ; credit added this frame? [$6802]
                                             ; 56XX credits added
C058: 84 0F           ANDA   #$0F
C05A: 27 4F           BEQ    irq_copy_sprites
C05C: 7C 60 56        INC    snd_request+22  ; coin sound [$6056]
C05F: 7F 68 02        CLR    IO56XX+$02      ; acknowledge the 56XX [$6802]
                                             ; 56XX credits added
C062: B6 09 F4        LDA    attract_flag    ; [$09F4]
C065: 27 44           BEQ    irq_copy_sprites

lC067:
C067: 96 AF           LDA    <frame_sync     ; coin during the demo: wait for
                                             ; the sub [$10AF]
C069: 81 11           CMPA   #$11
C06B: 26 FA           BNE    lC067
C06D: 0F DA           CLR    <capture_substate ; [$10DA]
C06F: 0F D9           CLR    <player_frozen  ; [$10D9]
C071: 7F 11 11        CLR    $1111
C074: 0F E9           CLR    <$E9            ; [$10E9]
C076: 0F CF           CLR    <$CF            ; [$10CF]
C078: 0F D0           CLR    <$D0            ; [$10D0]
C07A: 7F 60 51        CLR    snd_request+17  ; [$6051]
C07D: 7F 60 71        CLR    snd_active+17   ; [$6071]
C080: 7F 11 18        CLR    wing_group      ; [$1118]
C083: 7F 11 16        CLR    escort_step     ; [$1116]
C086: 7F 11 17        CLR    wing_sprite_idx ; [$1117]
C089: 0F 30           CLR    <main_task      ; [$1030]
C08B: 0F 7A           CLR    <sub_task       ; [$107A]
C08D: 0F 2F           CLR    <game_mode      ; [$102F]
C08F: 7F 1E 01        CLR    $1E01
C092: 7F 1F 17        CLR    $1F17
C095: 7F 1F 19        CLR    $1F19
C098: 7F 1F 1B        CLR    $1F1B
C09B: 7F 1F 1D        CLR    $1F1D
C09E: BD DF 5D        JSR    clear_sprite_shadows
C0A1: BD DF 27        JSR    sound_demo_gate
C0A4: 86 22           LDA    #$22
C0A6: 97 AF           STA    <frame_sync     ; [$10AF]
C0A8: 7E C4 17        JMP    attract_loop    ; restart attract (stack
                                             ; abandoned)

;------------------------------------------------------------------------------
; irq_copy_sprites  ($C0AB)
; -> src/game/main/gp2_3b_irq.js
; Copy the main CPU's sprites (shadow $0EE2-$0F33, bit 7 of the
; flag byte = in use) to sprite RAM from slot 40 ($0FD0) up.
; Jumped to from: $C05A, $C065
;------------------------------------------------------------------------------
; Sprite copy: main-owned sprites to sprite RAM slots 40-63.
irq_copy_sprites:
C0AB: CE 0E E2        LDU    #$0EE2
C0AE: 8E 0F D0        LDX    #SPRITE_RAM_1+$50 ; [#$0FD0]

