;------------------------------------------------------------------------------
; reset_main  ($E000)
; -> src/game/main/gp2_2b_boot.js
; Power-on / watchdog reset. Boot sequence:
;  1. hold sub + sound CPUs in reset (SRESET), let the I/O chips run,
;     mask the IRQ, DP = $10, S = $1600;
;  2. 56XX command 1 (read switches) with arg F, 58XX command 0;
;  3. fill the tilemap with $00,$20 pairs, clear $0400-$1FFF (kicking
;     the watchdog on every word);
;  4. starfield off, no flip; 62XX bytes 8-15 = 4..$0B;
;  5. custom-chip check: 56XX mode 8 (sum of args 9-15 = 7 x F = $69
;     -> nibbles 6,9), 58XX mode 5 (must give F,F), 62XX bytes 1-3
;     must read F,E,1. A failure hangs at $E0C5 with D = $2031/2/3
;     ('1'/'2'/'3' = which chip; nothing is drawn, only the code in D);
;  6. release SRESET and handshake: write $11 to $6040 (sound) and
;     $0800 (sub), wait until each answers $22 (their ROM checksum is
;     done);
;  7. write $0000 to $7820-$782F (lands on the IRQ-off latch, harmless);
;  8. 56XX/58XX command 0, then 56XX mode 1 (switches) / 58XX mode 4
;     (DIPs); copy switches to $1006-$1009; decode the DIP switches
;     into coinage, lives, difficulty, cabinet and bonus settings;
;  9. service switch on -> service_mode; else pulse FRESET, program
;     the coinage into the 56XX (mode 2) and go to game_init ($C296).
; Vector: RESET
; Jumped to from: $BDA8
;------------------------------------------------------------------------------
reset_main:
E000: 1A 10           ORCC   #$10            ; mask IRQ [DP differs on another
                                             ; path]
E002: B7 8C 00        STA    SRESET_ON       ; hold sub + sound CPUs in reset
                                             ; [$8C00]
E005: B7 94 00        STA    FRESET_OFF      ; I/O chips run [$9400]
E008: B7 7C 00        STA    IRQ_OFF_MAIN    ; main IRQ off [$7C00]
E00B: 86 10           LDA    #$10
E00D: 1F 8B           TFR    A,DP
E00F: 10 CE 16 00     LDS    #player_y       ; main stack below $1600 [#$1600]

; Custom I/O chips: 56XX command 1, 58XX command 0.
E013: CC 01 FF        LDD    #$01FF          ; 56XX: command 1 (switches), arg
                                             ; 9 = F
E016: FD 68 08        STD    IO56XX+$08      ; 56XX command 1 (switches), arg 9
                                             ; = F [$6808] 56XX command
E019: 7F 68 18        CLR    IO58XX+$08      ; 58XX: command 0 (nop) [$6818]
                                             ; 58XX command

; Clear the tilemap and all shared RAM.
E01C: 8E 00 00        LDX    #$0000          ; tilemap: $00,$20 pairs
E01F: CE 00 20        LDU    #TILE_RAM+$20   ; [#$0020]

lE022:
E022: EF 81           STU    ,X++            ; tilemap = $00,$20 pairs. 15
                                             ; cycles per word; each store
                                             ; lands in the frame it starts in
E024: 8C 04 00        CMPX   #$0400
E027: 26 F9           BNE    lE022
E029: CE 00 00        LDU    #$0000          ; clear $0400-$1FFF

lE02C:
E02C: 10 BE 7C 00     LDY    WATCHDOG        ; clear $0400-$1FFF. LDY reads
                                             ; $7C00 and $7C01: two watchdog
                                             ; kicks per word. 22 cycles per
                                             ; word; the store starts 7 cycles
                                             ; into the iteration [$7C00]
E030: EF 81           STU    ,X++
E032: 8C 20 00        CMPX   #$2000
E035: 26 F5           BNE    lE02C
E037: BD BE 25        JSR    delay_65536     ; wait for the chips
E03A: CC 00 00        LDD    #$0000
E03D: B7 A0 00        STA    STARFIELD       ; starfield off [$A000]
E040: F7 1F 7F        STB    FLIP_SCREEN     ; no flip [$1F7F]

; 62XX: bytes 8-15 = 4, 5, ..., $0B.
E043: C6 04           LDB    #$04
E045: F7 68 28        STB    IO62XX+$08      ; [$6828] 62XX mode
E048: 5C              INCB
E049: F7 68 29        STB    IO62XX+$09      ; [$6829] 62XX $6829 (>= $0F:
                                             ; bang)
E04C: 5C              INCB
E04D: F7 68 2A        STB    IO62XX+$0A      ; [$682A] 62XX byte 10
E050: 5C              INCB
E051: F7 68 2B        STB    IO62XX+$0B      ; [$682B] 62XX byte 11
E054: 5C              INCB
E055: F7 68 2C        STB    IO62XX+$0C      ; [$682C] 62XX byte 12
E058: 5C              INCB
E059: F7 68 2D        STB    IO62XX+$0D      ; [$682D] 62XX byte 13
E05C: 5C              INCB
E05D: F7 68 2E        STB    IO62XX+$0E      ; [$682E] 62XX byte 14
E060: 5C              INCB
E061: F7 68 2F        STB    IO62XX+$0F      ; [$682F] 62XX byte 15

; Chip self-check: 56XX mode 8 and 58XX mode 5 with args 9-15 = F.
E064: CC 08 0F        LDD    #$080F          ; 56XX mode 8 / 58XX mode 5 check
E067: CE 68 08        LDU    #IO56XX+$08     ; [#$6808] 56XX command
E06A: 8E 68 18        LDX    #IO58XX+$08     ; [#$6818] 58XX command
E06D: A7 C0           STA    ,U+
E06F: 86 05           LDA    #$05
E071: A7 80           STA    ,X+
E073: 17 DD AF        LBSR   delay_65536

lE076:
E076: E7 C0           STB    ,U+             ; args 9-15 = F on both chips,
                                             ; interleaved. 20 cycles per pass
E078: E7 80           STB    ,X+
E07A: 11 83 68 10     CMPU   #$6810
E07E: 26 F6           BNE    lE076
E080: 17 DD A2        LBSR   delay_65536
E083: FC 68 00        LDD    IO56XX          ; 56XX sum of args must be $69
                                             ; [$6800] 56XX credits tens
E086: 84 0F           ANDA   #$0F
E088: C4 0F           ANDB   #$0F
E08A: 10 83 06 09     CMPD   #$0609
E08E: 27 05           BEQ    lE095
E090: CC 20 31        LDD    #$2031          ; error '1': 56XX
E093: 20 30           BRA    boot_chip_error

lE095:
E095: FC 68 10        LDD    IO58XX          ; 58XX mode 5 must give F,F
                                             ; [$6810] 58XX DSWA hi
E098: 84 0F           ANDA   #$0F
E09A: C4 0F           ANDB   #$0F
E09C: 10 83 0F 0F     CMPD   #$0F0F
E0A0: 27 05           BEQ    lE0A7
E0A2: CC 20 32        LDD    #$2032          ; error '2': 58XX
E0A5: 20 1E           BRA    boot_chip_error

lE0A7:
E0A7: B6 68 21        LDA    IO62XX+$01      ; 62XX must read F,E,1 [$6821]
                                             ; 62XX byte 1
E0AA: 84 0F           ANDA   #$0F
E0AC: 81 0F           CMPA   #$0F
E0AE: 26 12           BNE    lE0C2
E0B0: B6 68 22        LDA    IO62XX+$02      ; [$6822] 62XX byte 2
E0B3: 84 0F           ANDA   #$0F
E0B5: 81 0E           CMPA   #$0E
E0B7: 26 09           BNE    lE0C2
E0B9: B6 68 23        LDA    IO62XX+$03      ; [$6823] 62XX byte 3
E0BC: 84 0F           ANDA   #$0F
E0BE: 81 01           CMPA   #$01
E0C0: 27 05           BEQ    boot_handshake

lE0C2:
E0C2: CC 20 33        LDD    #$2033          ; error '3': 62XX

;------------------------------------------------------------------------------
; boot_chip_error  ($E0C5)
; -> src/game/main/gp2_2b_boot.js
; Custom I/O chip check failed: hang (watchdog resets the board).
; Jumped to from: $E093, $E0A5, $E0C5
;------------------------------------------------------------------------------
boot_chip_error:
E0C5: 20 FE           BRA    boot_chip_error

;------------------------------------------------------------------------------
; boot_handshake  ($E0C7)
; -> src/game/main/gp2_2b_boot.js
; Release the sub and sound CPUs (SRESET off), write $11 to $6040 and $0800 and
; wait for both to answer $22; then read the switches and DIPs and decode them.
; Jumped to from: $E0C0
;------------------------------------------------------------------------------
; Start the sub and sound CPUs and wait for their checksums.
boot_handshake:
E0C7: B7 84 00        STA    SRESET_OFF      ; sub + sound CPUs start [$8400]
E0CA: 86 11           LDA    #$11            ; $11: start your ROM checksum
E0CC: B7 60 40        STA    snd_request     ; the sound and sub CPUs, running
                                             ; now, poll these: timing points
                                             ; [$6040]
E0CF: B7 08 00        STA    sub_handshake   ; [$0800]

lE0D2:
E0D2: B6 60 40        LDA    snd_request     ; wait for the sound CPU's $22
                                             ; [$6040]
E0D5: 10 BE 7C 00     LDY    WATCHDOG        ; [$7C00]
E0D9: 81 22           CMPA   #$22
E0DB: 26 F5           BNE    lE0D2

lE0DD:
E0DD: B6 08 00        LDA    sub_handshake   ; wait for the sub CPU's $22
                                             ; [$0800]
E0E0: 10 BE 7C 00     LDY    WATCHDOG        ; [$7C00]
E0E4: 81 22           CMPA   #$22
E0E6: 26 F5           BNE    lE0DD

; Clear $7820-$782F (IRQ-off latch range).
E0E8: CC 00 00        LDD    #$0000
E0EB: 8E 78 20        LDX    #$7820

lE0EE:
E0EE: ED 81           STD    ,X++            ; 15 cycles a pass; every byte
                                             ; written is an IRQ-off latch
                                             ; write
E0F0: 8C 78 30        CMPX   #$7830
E0F3: 26 F9           BNE    lE0EE

; Read the switches and DIP switches.
E0F5: B7 68 08        STA    IO56XX+$08      ; 56XX, 58XX command 0 [$6808]
                                             ; 56XX command
E0F8: B7 68 18        STA    IO58XX+$08      ; [$6818] 58XX command
E0FB: 4A              DECA
E0FC: BD BE 25        JSR    delay_65536
E0FF: CC 01 04        LDD    #$0104          ; 56XX mode 1, 58XX mode 4
E102: B7 68 08        STA    IO56XX+$08      ; [$6808] 56XX command
E105: F7 68 18        STB    IO58XX+$08      ; [$6818] 58XX command
E108: BD BE 25        JSR    delay_65536
E10B: CE 68 00        LDU    #IO56XX         ; copy the switch nibbles to $1006
                                             ; [#$6800] 56XX credits tens
E10E: 8E 10 06        LDX    #boot_switches  ; [#$1006]

lE111:
E111: A6 C0           LDA    ,U+             ; the switch nibbles to
                                             ; boot_switches $1006-$1009 (22
                                             ; cycles a pass; the store starts
                                             ; 8 cycles in)
E113: 84 0F           ANDA   #$0F
E115: A7 80           STA    ,X+
E117: 11 83 68 04     CMPU   #$6804
